def set_fonts_run(run, font):
    run.font.name=font
    rpr=run._element.get_or_add_rPr()
    rf=rpr.rFonts
    if rf is None:
        rf=OxmlElement('w:rFonts'); rpr.insert(0,rf)
    for a in ('ascii','hAnsi','eastAsia','cs'): rf.set(qn('w:'+a),font)

def setup_style(style_name,font,size,bold=False):
    st=doc.styles[style_name]; st.font.name=font; st.font.size=Pt(size); st.font.bold=bold
    rpr=st.element.get_or_add_rPr(); rf=rpr.rFonts
    if rf is None: rf=OxmlElement('w:rFonts'); rpr.insert(0,rf)
    for a in ('ascii','hAnsi','eastAsia','cs'): rf.set(qn('w:'+a),font)
for n in ['Normal','Body Text']:
    try: setup_style(n,'仿宋',11,False)
    except: pass
for n,sz in [('Title',20),('Heading 1',16),('Heading 2',13),('Heading 3',12)]: setup_style(n,'黑体',sz,True)

def p(text='',style=None,align=None,indent=True,after=5):
    para=doc.add_paragraph(style=style)
    if text:
        r=para.add_run(text); set_fonts_run(r,'黑体' if style in ('Title','Heading 1','Heading 2','Heading 3') else '仿宋')
    if align is not None: para.alignment=align
    if indent and style not in ('Title','Heading 1','Heading 2','Heading 3'): para.paragraph_format.first_line_indent=Cm(0.74)
    para.paragraph_format.space_after=Pt(after)
    return para

def heading(text,level=1):
    para=doc.add_paragraph(style=f'Heading {level}')
